#!/usr/bin/env bash
#
# agents-cron notification setup wizard: walks a human through enabling the
# email (QQ-style SMTP) and Feishu-bot channels, writes `.agents/cron/config.json`
# plus the secret-holding `.agents/cron/notify.env`, and tests each channel.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 </dev/null || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  if [[ -t 0 ]]; then
    read -e -r -p "$p" input || rc=1
  else
    printf '%s' "$p"; printf '\n'
    read -r input || rc=1
  fi
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  if [[ ! -e "$ENV_FILE" ]]; then mkdir -p "$(dirname "$ENV_FILE")"; (umask 077 && : > "$ENV_FILE"); fi
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  if (( ${#SKIPPED[@]} )); then
    printf '\n%s%s  Setup finished (with warnings)%s\n' "$BOLD" "$YELLOW" "$RESET"
  else
    printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# This wizard lives next to the CLI entry it drives.
WIZARD_BIN="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/agents-cron.mjs"
CONFIG_JSON=".agents/cron/config.json"
ENV_FILE="${AGENTS_CRON_NOTIFY_ENV:-.agents/cron/notify.env}"

# merge_channel <id> <channel-json> upserts one channel into CONFIG_JSON.
merge_channel() {
  node - "$CONFIG_JSON" "$1" "$2" <<'NODE'
const fs = require("fs");
const path = require("path");
const [file, id, channelJson] = process.argv.slice(2);
const channel = JSON.parse(channelJson);
let config = {};
try { config = JSON.parse(fs.readFileSync(file, "utf8")); } catch {}
config.notifications = config.notifications ?? {};
const channels = (config.notifications.channels ?? []).filter((c) => c.id !== id);
channels.push(channel);
config.notifications.channels = channels;
fs.mkdirSync(path.dirname(file), { recursive: true });
fs.writeFileSync(file, JSON.stringify(config, null, 2) + "\n");
NODE
  printf '  %s✓ wrote%s channel "%s" → %s\n' "$GREEN" "$RESET" "$1" "$CONFIG_JSON"
}

banner "agents-cron notifications"

# ── Choose channels (unnumbered: the count depends on this very answer) ──
say "Two push channels ship built in; pick either or both."
WANT_EMAIL=false; WANT_FEISHU=false
if confirm "Set up the email channel (QQ/Foxmail-style SMTP)?"; then WANT_EMAIL=true; fi
if confirm "Set up the Feishu (飞书) group-bot channel?"; then WANT_FEISHU=true; fi
if [[ "$WANT_EMAIL" == false && "$WANT_FEISHU" == false ]]; then
  warn "No channels selected — nothing to do. Re-run any time."
  exit 0
fi
_CHOSEN_STAGES=2
if [[ "$WANT_EMAIL" == true ]]; then _CHOSEN_STAGES=$((_CHOSEN_STAGES + 2)); fi
if [[ "$WANT_FEISHU" == true  ]]; then _CHOSEN_STAGES=$((_CHOSEN_STAGES + 1)); fi
TOTAL_STAGES=$_CHOSEN_STAGES
note "this run has $TOTAL_STAGES stages"

# ── Stage 2: email — enable SMTP, capture the authorization code ────────
if [[ "$WANT_EMAIL" == true ]]; then
  stage "Email: SMTP authorization code (授权码)"
  say "The mail provider's console is the only place this code can be born."
  open_url "https://mail.qq.com/"
  step "Log in, then 设置 (Settings) → 账号 (Account)."
  step "Find POP3/IMAP/SMTP 服务 and enable 发送邮件 (SMTP)."
  step "Generate an 授权码 (authorization code) — not your login password — and copy it."
  ask_secret AGENTS_CRON_SMTP_PASSWORD "Paste the 授权码:"
  write_env AGENTS_CRON_SMTP_PASSWORD "$AGENTS_CRON_SMTP_PASSWORD"
fi

# ── Stage 3: email — addresses, config, live test ────────────────────────
if [[ "$WANT_EMAIL" == true ]]; then
  stage "Email: addresses and test send"
  ask SMTP_HOST "SMTP host (Enter = smtp.qq.com):"
  [[ -z "$SMTP_HOST" ]] && SMTP_HOST="smtp.qq.com"
  ask SMTP_FROM "Sender address (also the SMTP user, e.g. you@foxmail.com):"
  if [[ "$SMTP_FROM" != *"@"* ]]; then
    warn "that address has no @; aborting email setup"
    note "any values already saved stay in $ENV_FILE — re-run the wizard and press Enter to keep them"
    exit 1
  fi
  ask SMTP_TO "Recipient address (Enter = same as sender: $SMTP_FROM):"
  [[ -z "$SMTP_TO" ]] && SMTP_TO="$SMTP_FROM"
  write_env SMTP_HOST "$SMTP_HOST"
  write_env SMTP_FROM "$SMTP_FROM"
  write_env SMTP_TO "$SMTP_TO"
  merge_channel email "{\"id\":\"email\",\"type\":\"email\",\"host\":\"$SMTP_HOST\",\"port\":465,\"user\":\"$SMTP_FROM\",\"from\":\"$SMTP_FROM\",\"to\":\"$SMTP_TO\"}"
  export AGENTS_CRON_SMTP_PASSWORD
  "$WIZARD_BIN" test-notify --channel email || warn "email test failed — check the 授权码 and re-run the wizard"
fi

# ── Stage 4: Feishu — create the group bot, capture the webhook ─────────
if [[ "$WANT_FEISHU" == true ]]; then
  stage "Feishu: group bot webhook"
  say "Feishu only takes messages from bots you create inside a group."
  step "Pick (or create) a group for task notifications."
  step "群设置 (group settings) → 群机器人 (bots) → 添加机器人 → 自定义机器人."
  step "Security: choose 自定义关键词 (custom keyword) and enter exactly: task"
  warn "Do NOT choose 签名校验 (signature) — the notifier cannot sign."
  step "Copy the webhook URL (https://open.feishu.cn/open-apis/bot/v2/hook/…)."
  ask FEISHU_WEBHOOK_URL "Paste the webhook URL:"
  if [[ "$FEISHU_WEBHOOK_URL" != https://* ]]; then
    warn "that is not an https URL; aborting Feishu setup"
    note "any values already saved stay in $ENV_FILE — re-run the wizard and press Enter to keep them"
    exit 1
  fi
  write_env FEISHU_WEBHOOK_URL "$FEISHU_WEBHOOK_URL"
  merge_channel feishu "{\"id\":\"feishu\",\"type\":\"webhook\",\"url\":\"$FEISHU_WEBHOOK_URL\",\"format\":\"feishu\"}"
  "$WIZARD_BIN" test-notify --channel feishu || warn "feishu test failed — check the webhook URL and keyword"
fi

# ── Stage 5: wire the environment (shell + cron) ────────────────────────
stage "Wire the environment"
NOTIFY_ENV_ABS="$PWD/.agents/cron/notify.env"
say "Interactive shells and cron both need the values in notify.env."
SOURCE_LINE="[ -f \"$NOTIFY_ENV_ABS\" ] && . \"$NOTIFY_ENV_ABS\""
if grep -qF "$NOTIFY_ENV_ABS" ~/.bashrc 2>/dev/null; then
  note "already sourced in ~/.bashrc — skipping"
else
  if confirm "Append the source line to ~/.bashrc?"; then
    printf '\n# agents-cron notification environment\n%s\n' "$SOURCE_LINE" >> ~/.bashrc
    printf '  %s✓ appended%s to ~/.bashrc\n' "$GREEN" "$RESET"
  fi
fi
say "Your crontab line should source it too, e.g.:"
printf '  %s\n' "*/5 * * * * . $NOTIFY_ENV_ABS && agents-cron run-due --all >> \"\$HOME/.agents/cron/cron.log\" 2>&1"
pause

# ── Stage 6: final verification ──────────────────────────────────────────
stage "Verify everything"
say "One live pass through every configured channel:"
set +e
if [[ "$WANT_EMAIL" == true ]]; then
  export AGENTS_CRON_SMTP_PASSWORD
  "$WIZARD_BIN" test-notify --channel email || SKIPPED+=("email channel")
fi
if [[ "$WANT_FEISHU" == true ]]; then
  "$WIZARD_BIN" test-notify --channel feishu || SKIPPED+=("feishu channel")
fi
set -e
pause "Done reading the results?"

finish
}

run_wizard "$@"; exit
